namespace sv_16c9c9bf0a9d4eb0ba0689784940489c.Client.Models;

public class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public DateTimeOffset? EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> StatusUpdates { get; init; }
}

public class StatusUpdate
{
    public required DateTimeOffset Timestamp { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
}

using sv_16c9c9bf0a9d4eb0ba0689784940489c.Client.Models;

namespace sv_16c9c9bf0a9d4eb0ba0689784940489c.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_16c9c9bf0a9d4eb0ba0689784940489c.Client.Models;
using sv_16c9c9bf0a9d4eb0ba0689784940489c.Client.Services;

namespace sv_16c9c9bf0a9d4eb0ba0689784940489c.Services;

public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 22, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 17, 9, 0, 0, TimeSpan.Zero), Status = "Picked Up", Location = "New York, NY" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 18, 14, 30, 0, TimeSpan.Zero), Status = "In Transit", Location = "Philadelphia, PA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 19, 8, 15, 0, TimeSpan.Zero), Status = "In Transit", Location = "Chicago, IL" },
            ]
        },
        ["TRK-2002"] = new Shipment
        {
            TrackingNumber = "TRK-2002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 18, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 15, 10, 0, 0, TimeSpan.Zero), Status = "Picked Up", Location = "Seattle, WA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 16, 16, 45, 0, TimeSpan.Zero), Status = "In Transit", Location = "Portland, OR" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 17, 11, 20, 0, TimeSpan.Zero), Status = "Out for Delivery", Location = "San Francisco, CA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 17, 14, 5, 0, TimeSpan.Zero), Status = "Delivered", Location = "San Francisco, CA" },
            ]
        },
        ["TRK-3003"] = new Shipment
        {
            TrackingNumber = "TRK-3003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 25, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 19, 7, 0, 0, TimeSpan.Zero), Status = "Processing", Location = "Dallas, TX" },
            ]
        },
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

using System.Net.Http.Json;
using sv_16c9c9bf0a9d4eb0ba0689784940489c.Client.Models;

namespace sv_16c9c9bf0a9d4eb0ba0689784940489c.Client.Services;

/// <summary>
/// IShipmentService implementation used when running on WebAssembly.
/// Calls the server API over HTTP.
/// </summary>
public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var encoded = Uri.EscapeDataString(trackingNumber);
        var response = await http.GetAsync($"api/shipments/{encoded}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

